describe('Modal Accessibility - Title Announcement', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.injectAxe();
  });

  it('should announce modal title to screen readers when modal opens', () => {
    cy.get('[data-testid="open-modal-btn"]').click();

    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="modal"]').should('have.attr', 'role', 'dialog');

    cy.get('[data-testid="modal-title"]').should('have.attr', 'id');

    cy.get('[data-testid="modal"]').should(
      'have.attr',
      'aria-labelledby',
      cy.get('[data-testid="modal-title"]').then($el => $el.attr('id'))
    );

    cy.get('[data-testid="modal-title"]').should('contain.text', 'Confirm Action');

    cy.checkA11y('[data-testid="modal"]', {
      rules: {
        'aria-required-attr': { enabled: true },
        'aria-valid-attr-role': { enabled: true }
      }
    });
  });

  it('should maintain title announcement when modal content updates', () => {
    cy.get('[data-testid="open-modal-btn"]').click();

    cy.get('[data-testid="modal"]').should('be.visible');

    const initialTitleId = cy.get('[data-testid="modal-title"]').then($el => $el.attr('id'));

    cy.get('[data-testid="modal-update-btn"]').click();

    cy.get('[data-testid="modal-title"]').should('contain.text', 'Updated Title');

    cy.get('[data-testid="modal"]').should('have.attr', 'aria-labelledby');

    cy.get('[data-testid="modal-title"]').then($el => {
      expect($el.attr('id')).to.equal(initialTitleId);
    });
  });

  it('should handle multiple modals with unique title announcements', () => {
    cy.get('[data-testid="open-modal-1-btn"]').click();

    cy.get('[data-testid="modal-1"]').should('be.visible');
    cy.get('[data-testid="modal-1-title"]').should('contain.text', 'Modal One');
    cy.get('[data-testid="modal-1"]').should('have.attr', 'aria-labelledby');

    cy.get('[data-testid="open-modal-2-btn"]').click();

    cy.get('[data-testid="modal-2"]').should('be.visible');
    cy.get('[data-testid="modal-2-title"]').should('contain.text', 'Modal Two');
    cy.get('[data-testid="modal-2"]').should('have.attr', 'aria-labelledby');

    cy.get('[data-testid="modal-1"]').should('not.be.visible');
  });

  it('should announce title when modal reopens after closing', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="modal-close-btn"]').click();
    cy.get('[data-testid="modal"]').should('not.be.visible');

    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="modal"]').should('have.attr', 'aria-labelledby');
    cy.get('[data-testid="modal-title"]').should('contain.text', 'Confirm Action');
  });

  it('should fail when modal lacks aria-labelledby attribute', () => {
    cy.get('[data-testid="open-broken-modal-btn"]').click();

    cy.get('[data-testid="broken-modal"]').should('be.visible');

    cy.get('[data-testid="broken-modal"]').should('not.have.attr', 'aria-labelledby');

    cy.checkA11y('[data-testid="broken-modal"]', {
      rules: {
        'aria-required-attr': { enabled: true }
      }
    }).then(results => {
      expect(results.violations.length).to.be.greaterThan(0);
    });
  });
});
